class Solution {
public:
    vector<int> twoOutOfThree(vector<int>& nums1, vector<int>& nums2, vector<int>& nums3) {
        int mask[101] = {0};
        for (int x : nums1) mask[x] |= 1;
        for (int x : nums2) mask[x] |= 2;
        for (int x : nums3) mask[x] |= 4;
        vector<int> result;
        for (int v = 1; v <= 100; ++v) {
            if ((mask[v] & (mask[v] - 1)) != 0) {
                result.push_back(v);
            }
        }
        return result;
    }
};
